(function () {
  "use strict";

  /**
   * Animate a panel open or closed.
   * Sets max-height to scrollHeight so CSS transition can run,
   * then clears it to allow the panel to grow if content changes.
   */
  function openPanel(panel) {
    panel.classList.add("is-open");
    panel.style.maxHeight = panel.scrollHeight + "px";

    // Once the transition ends, clear max-height so content can reflow freely
    panel.addEventListener(
      "transitionend",
      function onEnd(e) {
        if (e.propertyName === "max-height") {
          panel.style.maxHeight = "none";
          panel.removeEventListener("transitionend", onEnd);
        }
      }
    );
  }

  function closePanel(panel) {
    // Lock current height before transitioning to 0
    panel.style.maxHeight = panel.scrollHeight + "px";
    // Force reflow so the browser registers the explicit value
    void panel.offsetHeight;

    panel.style.maxHeight = "0";
    panel.classList.remove("is-open");
  }

  function toggleDisclosure(btn) {
    const expanded = btn.getAttribute("aria-expanded") === "true";
    const panelId = btn.getAttribute("aria-controls");
    const panel = document.getElementById(panelId);

    if (!panel) return;

    if (expanded) {
      btn.setAttribute("aria-expanded", "false");
      closePanel(panel);
    } else {
      btn.setAttribute("aria-expanded", "true");
      openPanel(panel);
    }
  }

  document.addEventListener("DOMContentLoaded", function () {
