    const buttons = document.querySelectorAll(".disclosure-btn");

    buttons.forEach(function (btn) {
      btn.addEventListener("click", function () {
        toggleDisclosure(btn);
      });

      // Keyboard: Enter and Space are handled natively for <button>,
      // but we guard against any non-button usage just in case.
