+  --text-secondary: #8b96aa;
+  --text-answer:    #c4cad6;
+  --icon-color:     #5b8dee;
+  --radius:         10px;
+  --transition:     220ms ease;
+}
+
+html {
+  font-size: 16px;
+  -webkit-text-size-adjust: 100%;
+}
+
+body {
+  background: var(--bg-page);
+  color: var(--text-primary);
+  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
+  line-height: 1.6;
+  min-height: 100vh;
+  padding: 2rem 1rem 4rem;
+}
+
+/* ── Skip link ── */
+.skip-link {
+  position: absolute;
+  top: -9999px;
+  left: 1rem;
+  background: var(--accent);
+  color: #fff;
+  padding: 0.5rem 1rem;
+  border-radius: var(--radius);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+}
+.skip-link:focus {
+  top: 1rem;
+  outline: 3px solid #fff;
+  outline-offset: 2px;
+}
+
+/* ── Page layout ── */
+.page-header {
+  text-align: center;
+  margin-bottom: 3rem;
+}
+
+.page-header .cat-icon {
+  font-size: 3rem;
+  display: block;
+  margin-bottom: 0.75rem;
+  line-height: 1;
+}
+
+.page-header h1 {
+  font-size: clamp(1.75rem, 4vw, 2.5rem);
+  font-weight: 700;
+  letter-spacing: -0.02em;
+  color: var(--text-primary);
+}
+
+.page-header p {
+  margin-top: 0.5rem;
+  color: var(--text-secondary);
+  font-size: 1.05rem;
+}
+
+.faq-container {
+  max-width: 780px;
+  margin: 0 auto;
+  width: 100%;
+}
+
+/* ── FAQ item ── */
+.example {
+  background: var(--bg-card);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  margin-bottom: 0.75rem;
+  overflow: hidden;
+  transition: border-color var(--transition), background var(--transition);
+}
+
+.example:has(.disclosure-btn[aria-expanded="true"]) {
+  border-color: var(--accent-dim);
+}
+
+/* ── Disclosure button ── */
+.disclosure-btn {
+  all: unset;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  width: 100%;
+  padding: 1.1rem 1.4rem;
+  cursor: pointer;
+  color: var(--text-primary);
+  font-size: 1rem;
+  font-weight: 600;
+  background: transparent;
+  transition: background var(--transition), color var(--transition);
+  border-radius: var(--radius);
+}
+
+.disclosure-btn:hover {
+  background: var(--bg-card-hover);
+  color: #fff;
+}
+
+.disclosure-btn:focus-visible {
+  outline: 2px solid var(--border-focus);
+  outline-offset: -2px;
+  border-radius: var(--radius);
+}
+
+/* force outline in forced-colors mode */
+@media (forced-colors: active) {
+  .disclosure-btn:focus-visible {
+    outline: 3px solid ButtonText;
+  }
+}
+
+.btn-text {
+  flex: 1;
+  text-align: left;
+}
+
+/* ── Chevron icon ── */
+.chevron {
+  flex-shrink: 0;
+  width: 1.25rem;
+  height: 1.25rem;
+  fill: none;
+  stroke: var(--icon-color);
+  stroke-width: 2.5;
+  stroke-linecap: round;
+  stroke-linejoin: round;
+  transition: transform var(--transition);
+  aria-hidden: true;
+}
+
+.disclosure-btn[aria-expanded="true"] .chevron {
+  transform: rotate(180deg);
+}
+
+/* ── Answer panel ── */
+.details {
+  overflow: hidden;
+  max-height: 0;
+  transition: max-height 280ms cubic-bezier(0.4, 0, 0.2, 1),
+              opacity   220ms ease;
+  opacity: 0;
+}
+
+.details.is-open {
+  opacity: 1;
+}
+
+.details-inner {
+  padding: 0 1.4rem 1.25rem 1.4rem;
+  color: var(--text-answer);
+  font-size: 0.975rem;
+  line-height: 1.7;
+  background: var(--bg-answer);
+  border-top: 1px solid var(--border);
+  padding-top: 1rem;
+}
+
+.details-inner p + p {
+  margin-top: 0.75rem;
+}
+
+.details-inner a {
+  color: var(--accent);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+
+.details-inner a:hover {
+  color: #7ba8f5;
+}
+
+/* ── Section label ── */
+.section-label {
+  font-size: 0.7rem;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--accent);
+  margin-bottom: 1rem;
+  padding-left: 0.25rem;
+}
+
+/* ── Reflow: 320 px ── */
+@media (max-width: 420px) {
+  body {
+    padding: 1rem 0.75rem 3rem;
+  }
+  .disclosure-btn {
+    padding: 1rem 1rem;
+  }
+  .details-inner {
+    padding: 0.9rem 1rem 1rem;
+  }
+}
+
')

